use std::io::{self, BufRead};

fn best(v: &Vec<(String, i64)>) -> Option<usize> {
    let mut b: Option<usize> = None;
    for (i, j) in v.iter().enumerate() {
        match b {
            None => b = Some(i),
            Some(k) => {
                if j.1 > v[k].1 {
                    b = Some(i);
                }
            }
        }
    }
    b
}

fn main() {
    let stdin = io::stdin();
    let mut q: Vec<(String, i64)> = Vec::new();
    let mut out = String::new();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let t: Vec<&str> = line.split_whitespace().collect();
        match t.as_slice() {
            ["add", name, p] => match p.parse::<i64>() {
                Ok(p) => q.push((name.to_string(), p)),
                Err(_) => out.push_str("error\n"),
            },
            ["pop"] => match best(&q) {
                Some(i) => {
                    let e = q.remove(i);
                    out.push_str(&format!("{}\n", e.0));
                }
                None => out.push_str("empty\n"),
            },
            ["peek"] => match best(&q) {
                Some(i) => out.push_str(&format!("{}\n", q[i].0)),
                None => out.push_str("empty\n"),
            },
            ["size"] => out.push_str(&format!("{}\n", q.len())),
            _ => out.push_str("error\n"),
        }
    }
    out.push_str("left:\n");
    while let Some(i) = best(&q) {
        let e = q.remove(i);
        out.push_str(&format!("{} {}\n", e.0, e.1));
    }
    print!("{}", out);
}

